{"task_id": "T24", "code": "def solve(line):
    """Parse a CSV line into fields.
    Handles fields optionally quoted with double quotes. Inside quoted fields,
    commas are literal and a pair of double quotes represents a literal quote.
    """
    fields = []
    field_chars = []
    i = 0
    n = len(line)
    in_quote = False
    while i < n:
        ch = line[i]
        if in_quote:
            if ch == '"':
                # Check for escaped double quote
                if i + 1 < n and line[i + 1] == '"':
                    field_chars.append('"')
                    i += 1  # skip the escaped quote
                else:
                    in_quote = False
            else:
                field_chars.append(ch)
        else:
            if ch == '"':
                in_quote = True
            elif ch == ',':
                fields.append(''.join(field_chars))
                field_chars = []
            else:
                field_chars.append(ch)
        i += 1
    # Append the final field (even for empty line, this yields [''])
    fields.append(''.join(field_chars))
